# Combine all 125 deduction items
ALL_DEDUCTION_RAW = CHUNK_1 + CHUNK_2 + CHUNK_3 + CHUNK_4
print(f"Total Deduction items gathered: {len(ALL_DEDUCTION_RAW)}")
assert len(ALL_DEDUCTION_RAW) == 125, f"Expected 125 deduction items, got {len(ALL_DEDUCTION_RAW)}"

deduction_questions = []
for idx, item in enumerate(ALL_DEDUCTION_RAW, start=126):
    target_uz, target_ru, target_en = item[0], item[1], item[2]
    dists_uz, dists_ru, dists_en = item[3], item[4], item[5]
    q_uz, q_ru, q_en = item[6], item[7], item[8]
    fact_uz, fact_ru, fact_en = item[9], item[10], item[11]
    aliases = item[12]

    # Balanced position: 0, 1, 2, 3
    pos = (idx - 126) % 4
    opts_uz = list(dists_uz)
    opts_ru = list(dists_ru)
    opts_en = list(dists_en)

    opts_uz.insert(pos, target_uz)
    opts_ru.insert(pos, target_ru)
    opts_en.insert(pos, target_en)

    q_dict = {
        "id": f"zakovat_{idx:03d}",
        "type": "deduction",
        "question": {
            "uz": f"Diqqat, mantiqiy savol: {q_uz}",
            "ru": f"Внимание, вопрос на логику: {q_ru}",
            "en": f"Attention, deductive question: {q_en}"
        },
        "options": {
            "uz": opts_uz,
            "ru": opts_ru,
            "en": opts_en
        },
        "correct_index": pos,
        "correct_answer": {
            "uz": target_uz,
            "ru": target_ru,
            "en": target_en
        },
        "image_url": None,
        "fun_fact": {
            "uz": fact_uz,
            "ru": fact_ru,
            "en": fact_en
        },
        "aliases": aliases
    }
    deduction_questions.append(q_dict)

out_path = os.path.join(os.path.dirname(__file__), "part2_deduction.py")
with open(out_path, "w", encoding="utf-8") as f:
    f.write("# -*- coding: utf-8 -*-\n")
    f.write('"""Part 2: Deduction questions (zakovat_126 to zakovat_250)."""\n\n')
    dumps_str = json.dumps(deduction_questions, ensure_ascii=False, indent=4)
    dumps_str = dumps_str.replace(': null', ': None')
    f.write("DEDUCTION_QUESTIONS = " + dumps_str + "\n")

print(f"Successfully generated {len(deduction_questions)} Deduction questions at {out_path}!")
